/// The query parameters of api.parties.index.
#[derive(Debug, Clone, Default, PartialEq)]
#[non_exhaustive]
pub struct PartiesListParams {
    /// Items a page, 1 to 100.
    pub limit: Option<u32>,
    /// The cursor of the page asked for; the first when None.
    pub cursor: Option<String>,
    /// Only people (PERSON) or only companies (BUSINESS).
    pub kind: Option<String>,
    /// Only the person or company with this CPF or CNPJ, matched exactly, with or without punctuation. A CNPJ may be alphanumeric.
    pub document: Option<String>,
}

impl PartiesListParams {
    /// No parameter set: the API's defaults and the first page.
    pub fn new() -> Self {
        Self::default()
    }

    /// Sets the items a page, 1 to 100.
    pub fn limit(mut self, limit: u32) -> Self {
        self.limit = Some(limit);
        self
    }

    /// Sets the cursor of the page asked for: a page's `next_cursor`.
    pub fn cursor(mut self, cursor: impl Into<String>) -> Self {
        self.cursor = Some(cursor.into());
        self
    }

    /// Only people (PERSON) or only companies (BUSINESS).
    pub fn kind(mut self, kind: impl Into<String>) -> Self {
        self.kind = Some(kind.into());
        self
    }

    /// Only the person or company with this CPF or CNPJ, matched exactly, with or without punctuation. A CNPJ may be alphanumeric.
    pub fn document(mut self, document: impl Into<String>) -> Self {
        self.document = Some(document.into());
        self
    }

    fn query(&self) -> Vec<(&'static str, String)> {
        let mut query = Vec::new();
        if let Some(limit) = self.limit {
            query.push(("limit", limit.to_string()));
        }
        if let Some(cursor) = &self.cursor {
            query.push(("cursor", cursor.clone()));
        }
        if let Some(value) = &self.kind {
            query.push(("kind", value.clone()));
        }
        if let Some(value) = &self.document {
            query.push(("document", value.clone()));
        }
        query
    }
}

